"""Enumerate all counterfactual-prime factorizations of numbers in the Hilbert monoid."""
from __future__ import annotations


def in_H(n: int) -> bool:
    return n % 4 == 1


def is_H_irreducible(n: int) -> bool:
    if n < 2 or not in_H(n):
        return False
    a = 1
    while a * a <= n:
        if n % a == 0:
            b = n // a
            if a > 1 and b > 1 and in_H(a) and in_H(b):
                return False
        a += 1
    return True


def H_factorizations(n: int) -> list[tuple[int, ...]]:
    irr = [m for m in range(2, n + 1) if is_H_irreducible(m)]
    out: set[tuple[int, ...]] = set()

    def rec(rem: int, start: int, acc: list[int]) -> None:
        if rem == 1:
            if acc:
                out.add(tuple(sorted(acc)))
            return
        for p in irr:
            if p < start or p > rem:
                continue
            if rem % p == 0:
                acc.append(p)
                rec(rem // p, p, acc)
                acc.pop()

    rec(n, 2, [])
    return sorted(out)


if __name__ == "__main__":
    for n in (45, 405, 441, 693, 1089):
        if in_H(n):
            print(n, "->", H_factorizations(n))

"""Compute the elasticity of the Hilbert monoid up to a bound: max ratio of
longest to shortest factorization length among elements with >= 2 factorizations."""
from __future__ import annotations


def in_H(n: int) -> bool:
    return n % 4 == 1


def is_H_irreducible(n: int) -> bool:
    if n < 2 or not in_H(n):
        return False
    a = 1
    while a * a <= n:
        if n % a == 0 and a > 1 and (n // a) > 1 and in_H(a) and in_H(n // a):
            return False
        a += 1
    return True


def factor_lengths(n: int) -> list[int]:
    irr = [m for m in range(2, n + 1) if is_H_irreducible(m)]
    lengths: set[int] = set()

    def rec(rem: int, start: int, depth: int) -> None:
        if rem == 1:
            if depth > 0:
                lengths.add(depth)
            return
        for p in irr:
            if p < start or p > rem:
                continue
            if rem % p == 0:
                rec(rem // p, p, depth + 1)

    rec(n, 2, 0)
    return sorted(lengths)


def elasticity(limit: int) -> float:
    best = 1.0
    for n in range(5, limit + 1):
        if in_H(n):
            ls = factor_lengths(n)
            if len(ls) >= 1 and ls:
                r = max(ls) / min(ls)
                best = max(best, r)
    return best


if __name__ == "__main__":
    print("Elasticity of H up to 5000:", elasticity(5000))

"""Show that the counterfactual primes below N split into two families:
'imported' rational primes p = 1 (mod 4), and 'promoted' composites whose
only rational factors lie in the forbidden class 3 (mod 4)."""
from __future__ import annotations


def in_H(n: int) -> bool:
    return n % 4 == 1


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def is_H_irreducible(n: int) -> bool:
    if n < 2 or not in_H(n):
        return False
    a = 1
    while a * a <= n:
        if n % a == 0 and a > 1 and (n // a) > 1 and in_H(a) and in_H(n // a):
            return False
        a += 1
    return True


if __name__ == "__main__":
    N = 120
    imported, promoted = [], []
    for n in range(2, N):
        if is_H_irreducible(n):
            (imported if is_prime(n) else promoted).append(n)
    print("Imported (rational primes = 1 mod 4):", imported)
    print("Promoted (composite counterfactual primes):", promoted)

